sys_variable_value.value:
(function execute(inputs, outputs) {
    var tr = inputs.trigger_record;
    var intSysId = tr.sys_id.toString();
    var appSysId = tr.application.toString();
    var reqSysId = tr.application.requisition.toString();
    var roleTitle = tr.application.requisition.role_title.toString();
    var interviewType = tr.interview_type.getDisplayValue();

    // ── 1. Collect all feedback records for this interview ──
    var fbGr = new GlideRecord('x_snc_aegis_interview_feedback');
    fbGr.addQuery('interview', intSysId);
    fbGr.addQuery('feedback_status', 'SUBMITTED');
    fbGr.query();

    var feedbackEntries = [];
    var totalTech = 0, totalComm = 0, totalCulture = 0, totalOverall = 0;
    var count = 0;
    var recommendations = { STRONG_YES: 0, YES: 0, NEUTRAL: 0, NO: 0, STRONG_NO: 0 };

    while (fbGr.next()) {
        count++;
        var entry = {
            panelist: fbGr.panellist.getDisplayValue(),
            technical_score: parseFloat(fbGr.getValue('technical_score')) || 0,
            communication_score: parseFloat(fbGr.getValue('communication_score')) || 0,
            culture_score: parseFloat(fbGr.getValue('culture_score')) || 0,
            overall_score: parseFloat(fbGr.getValue('overall_score')) || 0,
            recommendation: fbGr.getValue('recommendation'),
            strengths: fbGr.getValue('strengths_noted') || '',
            concerns: fbGr.getValue('concerns_noted') || '',
            comments: fbGr.getValue('verbatim_comments') || ''
        };
        feedbackEntries.push(entry);

        totalTech += entry.technical_score;
        totalComm += entry.communication_score;
        totalCulture += entry.culture_score;
        totalOverall += entry.overall_score;

        var rec = entry.recommendation;
        if (recommendations[rec] !== undefined) recommendations[rec]++;
    }

    if (count === 0) {
        outputs.success = false;
        outputs.synthesis = 'No submitted feedback found for this interview.';
        return;
    }

    // ── 2. Calculate averages ──
    var avgTech = Math.round((totalTech / count) * 10) / 10;
    var avgComm = Math.round((totalComm / count) * 10) / 10;
    var avgCulture = Math.round((totalCulture / count) * 10) / 10;
    var avgOverall = Math.round((totalOverall / count) * 10) / 10;

    // ── 3. Determine consensus ──
    var positiveVotes = recommendations.STRONG_YES + recommendations.YES;
    var negativeVotes = recommendations.NO + recommendations.STRONG_NO;
    var consensus = 'MIXED';
    if (positiveVotes > count * 0.6) consensus = 'POSITIVE';
    if (negativeVotes > count * 0.6) consensus = 'NEGATIVE';

    // ── 4. Aggregate strengths and concerns ──
    var allStrengths = [];
    var allConcerns = [];
    for (var i = 0; i < feedbackEntries.length; i++) {
        if (feedbackEntries[i].strengths) allStrengths.push(feedbackEntries[i].panelist + ': ' + feedbackEntries[i].strengths);
        if (feedbackEntries[i].concerns) allConcerns.push(feedbackEntries[i].panelist + ': ' + feedbackEntries[i].concerns);
    }

    // ── 5. Build synthesis text ──
    var synthesis = '';
    synthesis += '=== FEEDBACK SYNTHESIS: ' + interviewType + ' Round ===\n';
    synthesis += 'Role: ' + roleTitle + '\n';
    synthesis += 'Panelists Responded: ' + count + '\n';
    synthesis += 'Synthesized: ' + new GlideDateTime().getDisplayValue() + '\n\n';

    synthesis += '--- SCORE AVERAGES ---\n';
    synthesis += 'Technical Competency: ' + avgTech + '/5\n';
    synthesis += 'Communication Skills: ' + avgComm + '/5\n';
    synthesis += 'Cultural Alignment:   ' + avgCulture + '/5\n';
    synthesis += 'Overall Rating:       ' + avgOverall + '/5\n\n';

    synthesis += '--- RECOMMENDATION DISTRIBUTION ---\n';
    synthesis += 'Strong Yes: ' + recommendations.STRONG_YES + ' | Yes: ' + recommendations.YES +
        ' | Neutral: ' + recommendations.NEUTRAL +
        ' | No: ' + recommendations.NO + ' | Strong No: ' + recommendations.STRONG_NO + '\n';
    synthesis += 'Consensus: ' + consensus + '\n\n';

    synthesis += '--- KEY STRENGTHS (aggregated) ---\n';
    for (var s = 0; s < allStrengths.length; s++) {
        synthesis += '• ' + allStrengths[s] + '\n';
    }

    synthesis += '\n--- KEY CONCERNS (aggregated) ---\n';
    for (var c = 0; c < allConcerns.length; c++) {
        synthesis += '• ' + allConcerns[c] + '\n';
    }

    synthesis += '\n--- PANEL VERDICT ---\n';
    if (consensus === 'POSITIVE') {
        synthesis += 'The panel recommends advancing this candidate. Strong alignment on technical capability and team fit.';
    } else if (consensus === 'NEGATIVE') {
        synthesis += 'The panel does not recommend advancing this candidate. Significant concerns noted.';
    } else {
        synthesis += 'The panel is split. Recommend recruiter/hiring manager review of individual feedback before proceeding.';
    }

    // ── 6. Update Interview record ──
    var intGr = new GlideRecord('x_snc_aegis_interview');
    if (intGr.get(intSysId)) {
        intGr.setValue('feedback_synthesis', synthesis);
        intGr.setValue('synthesis_status', 'COMPLETED');
        intGr.setValue('outcome', consensus);
        intGr.update();
    }

    // ── 7. Log ──
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Feedback Synthesizer',
        'FEEDBACK_SYNTHESIS',
        appSysId,
        reqSysId,
        count + ' panelists | Avg Technical: ' + avgTech + ' | Avg Overall: ' + avgOverall,
        'Consensus: ' + consensus + ' | Recommendation distribution: SY=' +
            recommendations.STRONG_YES + ' Y=' + recommendations.YES +
            ' N=' + recommendations.NEUTRAL + ' NO=' + recommendations.NO +
            ' SNO=' + recommendations.STRONG_NO,
        avgOverall / 5,
        'Weighted average synthesis; Verbatim comments preserved immutably by BR-5'
    );

    outputs.success = true;
    outputs.synthesis = synthesis;
    outputs.consensus = consensus;

})(inputs, outputs);

